public static class RandomizedSetHarness
{
    // insert and remove report their booleans; getRandom is called 300 times and reports
    // whether every pick was a current member and every member was picked at least once.
    public static List<bool> Run(string[] ops, int[][] args)
    {
        var set = new RandomizedSet();
        var shadow = new HashSet<int>();
        var results = new List<bool>();
        for (var i = 0; i < ops.Length; i++)
        {
            if (ops[i] == "insert")
            {
                results.Add(set.Insert(args[i][0]));
                shadow.Add(args[i][0]);
            }
            else if (ops[i] == "remove")
            {
                results.Add(set.Remove(args[i][0]));
                shadow.Remove(args[i][0]);
            }
            else
            {
                var seen = new HashSet<int>();
                var ok = true;
                for (var t = 0; t < 300; t++)
                {
                    var v = set.GetRandom();
                    if (!shadow.Contains(v)) ok = false;
                    seen.Add(v);
                }
                results.Add(ok && seen.SetEquals(shadow));
            }
        }
        return results;
    }
}

